233: export const submitPublicEnquiry = createServerFn({ method: "POST" })
234:   .validator(
235:     (
236:       input: {
237:         name: string;
238:         email: string;
239:         message: string;
240:         website?: string;
241:         desk?: boolean;
242:         matter?: string;
243:       } & ServiceIntake,
244:     ) => input,
245:   )
246:   .handler(async ({ data }) => {
247:     if (str(data.website, 200).trim()) return { ok: true as const };
248:     const name = str(data.name, 400).trim();
249:     const email = str(data.email, 400).trim();
250:     const message = str(data.message, 6000).trim();
251:     const matter = serviceMatter(data.matter);
252:     const desk = data.desk === true || matter !== undefined;
253:     const serviceIntake = desk ? { ok: true as const, summary: "" } : formatServiceIntake(data);
254:     if (!serviceIntake.ok) return { ok: false as const, error: serviceIntake.error };
255:     if (name.length < 2 || name.length > 160) {
256:       return { ok: false as const, error: "Enter the name we should use." };
257:     }
258:     if (!validEmail(email)) {
259:       return { ok: false as const, error: "Enter a real email address." };
260:     }
261:     if (message.length < 5 || message.length > 3000) {
262:       return { ok: false as const, error: "Describe the work in a few sentences." };
263:     }
264:     let request: Request | undefined;
265:     try {
266:       const server = await import("@tanstack/react-start/server");
267:       request = server.getRequest();
268:     } catch {
269:       request = undefined;
270:     }
271:     if (!(await allowEnquiry(callerKey(request)))) {
272:       return {
273:         ok: false as const,
274:         error: "Too many enquiries from this connection. Try again later.",
275:       };
276:     }
277:     const subject = message.replace(/\s+/g, " ").slice(0, 90);
278:     const serviceDetails = serviceIntake.summary;
279:     const source = desk
280:       ? "Source: vantage-ars.co.za customer service desk. No automated reply sent."
281:       : "Source: vantage-ars.co.za enquiry form. No automated reply sent.";
282:     const id = await logInboundItem({
283:       channel: "web",
284:       companyName: name,
285:       subject,
286:       summary: `Email: ${email}\n${source}${matter ? `\nMatter: ${matter}` : ""}${serviceDetails ? `\n${serviceDetails}` : ""}\n\n${message}`,
287:       intent: desk ? "support" : "enquiry",
288:     });
289:     const snapshot = await readSnapshot();
290:     if (!snapshot.company.halted) {
291:       try {
292:         await processWebsiteEnquiry({ inboundId: id, name, message, desk, matter });
293:       } catch {
294:         // The enquiry is already on file. Routing can be retried from the inbox.
295:       }
296:     }
297:     try {
298:       const { deliverFounderNotice } = await import("./notify.server");
299:       await deliverFounderNotice(
300:         founderEnquiryNotice({
301:           name,
302:           email,
303:           subject,
304:           desk,
305:           excerpt: serviceDetails ? `${serviceDetails}\n\n${message}` : message,
306:         }),
307:       );
308:     } catch {
309:       // The enquiry is already on file.
310:     }
311:     return { ok: true as const };
312:   });
