492:     const plan = await proposeActions({
493:       agentId: "foyer",
494:       task: [
495:         `Route inbound ${id} from company "${companyName}".`,
496:         `Channel: ${data.channel.trim() || "direct"}. Intent: ${data.intent.trim() || "unclassified"}.`,
497:         `Subject: ${subject}`,
498:         `Summary: ${summary}`,
499:         "Use relatedId of the inbound item. Create a lead only if this is genuine demand.",
500:         "Do not sell, quote, or spend. If it is support, open a ticket for FORGE.",
501:       ].join("\n"),
502:       state: compactState(snapshot),
