515:     return {
516:       ok: true as const,
517:       id,
518:       routed: true as const,
519:       briefing: dispatch.briefing,
520:       executed: dispatch.executed,
521:       escalated: dispatch.escalated,
522:       blocked: dispatch.blocked,
523:     };
