268: /**
269:  * Cash may only retire money owed. Never credit more than the outstanding
270:  * receivable, and never credit at all when nothing is outstanding. Returns the
271:  * amount actually applied.
272:  */
273: async function applyReceiptAgainstReceivable(sql: Sql, amount: number): Promise<number> {
274:   if (amount <= 0) return 0;
275:   const rows = await sql<{ receivable_cents: number }>`
276:     select receivable_cents from company_state where id = ${COMPANY.id} for update
277:   `;
278:   const outstanding = Math.max(0, num(rows[0]?.receivable_cents));
279:   const applied = Math.min(amount, outstanding);
280:   if (applied <= 0) return 0;
281:   await sql`
282:     update company_state
283:     set treasury_cents = treasury_cents + ${applied},
284:         receivable_cents = receivable_cents - ${applied},
285:         updated_at = now()
286:     where id = ${COMPANY.id}
287:   `;
288:   return applied;
289: }
