291: /**
292:  * Provision the office if it is not there yet, and converge the roster.
293:  *
294:  * Runs at most once per process: `readSnapshot` used to call this on every page
295:  * load, which meant nine pointless `UPDATE agents` statements (each taking a row
296:  * lock and bloating `xmin`) on every office render and every public quote-link
297:  * view. Callers still get a correct roster because convergence is cheap and
298:  * idempotent once the flag is set.
299:  */
300: let provisionPromise: Promise<void> | null = null;
301: 
302: export function ensureOffice(): Promise<void> {
303:   provisionPromise ??= provisionOffice().catch((err) => {
304:     provisionPromise = null; // let the next caller retry
305:     throw err;
306:   });
307:   return provisionPromise;
308: }
