310: async function provisionOffice(): Promise<void> {
311:   const sql = await getSql();
312:   const existing = await sql<{ id: string }>`select id from company_state where id = ${COMPANY.id}`;
313:   if (existing.length) {
314:     await syncRoster(sql);
315:     await seedPaymentInstructions(sql);
316:     return;
317:   }
318: 
319:   await sql.transaction(async (tx) => {
320:     const raced = await tx<{
321:       id: string;
322:     }>`select id from company_state where id = ${COMPANY.id} for update`;
323:     if (raced.length) return;
324: 
325:     await tx`
326:       insert into company_state (
327:         id, legal_name, trading_name, domain, jurisdiction, timezone, currency, vat_rate,
328:         author_name, author_role, constitution_version, treasury_cents, receivable_cents,
329:         payable_cents, autonomy_level, halted, last_audit_hash, payment_instructions
330:       ) values (
331:         ${COMPANY.id}, ${COMPANY.legalName}, ${COMPANY.tradingName}, ${COMPANY.domain},
332:         ${COMPANY.jurisdiction}, ${COMPANY.timezone}, ${COMPANY.currency}, ${COMPANY.vatRate},
333:         ${COMPANY.authorName}, ${COMPANY.authorRole}, ${COMPANY.constitutionVersion},
334:         0, 0, 0, ${COMPANY.autonomyLevel}, false, ${GENESIS_HASH},
335:         ${paymentInstructionsText(process.env)}
336:       )
337:     `;
338: 
339:     for (const p of CONSTITUTION) {
340:       await tx`
341:         insert into constitution_provisions (
342:           id, article_id, title, priority, body, enforcement, machine_checkable, parameters_json
343:         ) values (
344:           ${p.id}, ${p.articleId}, ${p.title}, ${p.priority}, ${p.body}, ${p.enforcement},
345:           ${p.machineCheckable}, ${JSON.stringify(p.parameters)}
346:         )
347:       `;
348:     }
349: 
350:     for (const a of AGENT_DEFS) {
351:       await insertAgent(tx, a);
352:     }
353: 
354:     // The genesis audit row is written inside the same transaction so a
355:     // provisioned office is never missing its founding record.
356:     const previous = GENESIS_HASH;
357:     const id = randomUUID();
358:     const body =
359:       "Constitution v1.1.0 ratified by Juan-louw Greyling. Nine non-human identities issued. Treasury R0.00. Autonomy A3 within role; founder gates on cost, customer win, customer loss, and marketing-to-sales handoff, with a standing delegation available under ART-13.";
360:     const recordHash = chainHash(previous, {
361:       id,
362:       kind: "office_open",
363:       title: "Office provisioned",
364:       body,
365:       actor: "constitution",
366:     });
367:     await tx`
368:       insert into audit_events (id, kind, title, body, actor, previous_hash, record_hash)
369:       values (${id}, 'office_open', 'Office provisioned', ${body}, 'constitution', ${previous}, ${recordHash})
370:     `;
371:     await tx`
372:       update company_state set last_audit_hash = ${recordHash}, updated_at = now()
373:       where id = ${COMPANY.id}
374:     `;
375:   });
376: 
377:   await seedPaymentInstructions(sql);
378: }
