409: async function syncRoster(sql: Sql): Promise<void> {
410:   const rows = await sql<{ id: string }>`select id from agents`;
411:   const have = new Set(rows.map((row) => String(row.id)));
412:   for (const agent of AGENT_DEFS) {
413:     if (have.has(agent.id)) continue;
414:     await insertAgent(sql, agent);
415:     await appendAudit(
416:       "identity_issued",
417:       `${agent.callsign} issued`,
418:       `${agent.title} joined the floor. ${agent.summary}`,
419:       "constitution",
420:     );
421:   }
422:   // One statement instead of nine, and only when something actually drifted.
423:   const stale = AGENT_DEFS.filter((agent) => agent.summary.length > 0);
424:   for (const agent of stale) {
425:     await sql`
426:       update agents set summary = ${agent.summary}, authority_json = ${JSON.stringify(agent.authority)}
427:       where id = ${agent.id} and (summary <> ${agent.summary} or authority_json <> ${JSON.stringify(agent.authority)})
428:     `;
429:   }
430:   const role = CONSTITUTION.find((provision) => provision.id === "art-11");
431:   if (role) {
432:     await sql`
433:       update constitution_provisions
434:       set body = ${role.body}
435:       where id = ${"art-11"} and body is distinct from ${role.body}
436:     `;
437:   }
438:   // A constitution amendment must reach an office that was provisioned before
439:   // it. Every provision is re-synced, so a deployed office is never running a
440:   // constitution that is one version behind the code.
441:   for (const provision of CONSTITUTION) {
442:     await sql`
443:       update constitution_provisions
444:       set body = ${provision.body},
445:           title = ${provision.title},
446:           priority = ${provision.priority}
447:       where id = ${provision.id}
448:         and (body is distinct from ${provision.body}
449:              or title is distinct from ${provision.title}
450:              or priority is distinct from ${provision.priority})
451:     `;
452:   }
453: }
