534: /**
535:  * The autonomy health the founder sees on /office/metrics.
536:  *
537:  * Previously `hardViolations` was hardcoded to 0, which made
538:  * `constraintAdherence` a constant 1 — a blocked action was invisible in the
539:  * headline number. Every term below is now derived from rows that exist.
540:  */
541: function healthOf(
542:   company: CompanySnapshot,
543:   decisions: DecisionRow[],
544:   approvals: ApprovalRow[],
545: ): AutonomyHealth {
546:   const total = decisions.length;
547:   const blocked = decisions.filter((d) => d.status === "blocked").length;
548:   const escalated = decisions.filter((d) => d.status === "escalated").length;
549:   const executed = decisions.filter(
550:     (d) => d.status === "executed" || d.status === "authorized",
551:   ).length;
552:   const pending = approvals.filter((a) => a.status === "pending").length;
553:   const resolved = approvals.filter((a) => a.status !== "pending").length;
554:   // A block is the system refusing to act. That is the constitution working, not
555:   // a failure — but a rising count means an agent keeps trying the same thing.
556:   const hardViolations = blocked;
557:   const interventionRate = total === 0 ? 0 : escalated / total;
558:   const autonomousResolution = total === 0 ? 1 : executed / total;
559:   // Hard blocks are expected to be rare. Above ~2% the fleet is pushing.
560:   const constraintAdherence =
561:     total === 0 ? 1 : Math.max(0, 1 - hardViolations / Math.max(total, 1));
562:   const decisionQuality = total === 0 ? 1 : Math.max(0, 1 - blocked / Math.max(total, 1));
563:   const governance = company.halted ? 0.4 : 0.98;
564:   // Backlog of unresolved founder gates is the one thing that silently rots.
565:   const selfHealing = pending > 20 ? 0.7 : pending > 8 ? 0.84 : 0.94;
566:   const overall =
567:     constraintAdherence * 0.3 +
568:     decisionQuality * 0.2 +
569:     governance * 0.2 +
570:     selfHealing * 0.15 +
571:     autonomousResolution * 0.15;
572:   return {
573:     overall: Number(overall.toFixed(3)),
574:     decisionQuality: Number(decisionQuality.toFixed(3)),
575:     constraintAdherence: Number(constraintAdherence.toFixed(3)),
576:     selfHealing,
577:     governance,
578:     interventionRate: Number(interventionRate.toFixed(5)),
579:     autonomousResolution: Number(autonomousResolution.toFixed(4)),
580:     decisionCount: total,
581:     pendingApprovals: pending,
582:     hardViolations,
583:     resolvedApprovals: resolved,
584:   };
585: }
