840: /**
841:  * Resolve the opportunity an action is actually about.
842:  *
843:  * The governor used to ask only "does this customer have a won job or an
844:  * accepted quote somewhere?", which let one accepted job authorise an invoice
845:  * for a different job at the same customer. Follow the action's subject —
846:  * opportunity, billing cycle, subscription, invoice or quote document — to the
847:  * opportunity it belongs to, and fall back to the customer check only when the
848:  * subject cannot be resolved.
849:  */
850: async function opportunityIdForAction(sql: Sql, action: ProposedAction): Promise<string | null> {
851:   const payloadOpportunity =
852:     typeof action.payload.opportunityId === "string" ? action.payload.opportunityId.trim() : "";
853:   let candidate =
854:     payloadOpportunity || (typeof action.relatedId === "string" ? action.relatedId.trim() : "");
855:   for (let hop = 0; hop < 4 && candidate; hop += 1) {
856:     const opportunity = await sql<{ id: string }>`
857:       select id from opportunities where id = ${candidate} limit 1
858:     `;
859:     if (opportunity.length) return String(opportunity[0].id);
860: 
861:     const cycle = await sql<{ subscription_id: string }>`
862:       select subscription_id from billing_cycles where id = ${candidate} limit 1
863:     `.then((rows) => rows[0]);
864:     if (cycle?.subscription_id) {
865:       candidate = String(cycle.subscription_id);
866:       continue;
867:     }
868: 
869:     const subscription = await sql<{ opportunity_id: string | null }>`
870:       select opportunity_id from subscriptions where id = ${candidate} limit 1
871:     `.then((rows) => rows[0]);
872:     if (subscription?.opportunity_id) {
873:       candidate = String(subscription.opportunity_id);
874:       continue;
875:     }
876: 
877:     const document = await sql<{ related_id: string | null }>`
878:       select related_id from documents where id = ${candidate} limit 1
879:     `.then((rows) => rows[0]);
880:     if (document?.related_id && document.related_id !== candidate) {
881:       candidate = String(document.related_id);
882:       continue;
883:     }
884: 
885:     const invoice = await sql<{ related_id: string | null }>`
886:       select related_id from ledger_entries where id = ${candidate} and kind = 'invoice' limit 1
887:     `.then((rows) => rows[0]);
888:     if (invoice?.related_id && invoice.related_id !== candidate) {
889:       candidate = String(invoice.related_id);
890:       continue;
891:     }
892:     break;
893:   }
894:   return null;
895: }
