918: function mapDelegation(row: Record<string, unknown>): DelegationPolicy {
919:   const actions = parseJson<string[]>(row.allowed_actions_json, []).filter(
920:     (action): action is DelegationAction =>
921:       (DELEGATABLE_ACTIONS as readonly string[]).includes(action as string),
922:   );
923:   const rates = parseJson<string[]>(row.allowed_rate_ids_json, []).filter((id) =>
924:     delegatableRateIds().includes(id),
925:   );
926:   return {
927:     id: String(row.id),
928:     label: String(row.label ?? "Delegation"),
929:     status: (String(row.status) as DelegationPolicy["status"]) || "active",
930:     maxAmountCents: num(row.max_amount_cents, 500000),
931:     maxActionsPerDay: num(row.max_actions_per_day, 20),
932:     maxActionsPerMonth: num(row.max_actions_per_month, 200),
933:     allowedActions: actions,
934:     allowedRateIds: rates,
935:     allowCustomerMail: bool(row.allow_customer_mail),
936:     allowAutoReconcile: bool(row.allow_auto_reconcile),
937:     requireAcceptedQuote: bool(row.require_accepted_quote),
938:     createdAt: iso(row.created_at),
939:     updatedAt: iso(row.updated_at),
940:     revokedAt: row.revoked_at ? iso(row.revoked_at) : null,
941:   };
942: }
