944: async function readDelegationTx(sql: Sql): Promise<DelegationPolicy | null> {
945:   const rows = await sql<Record<string, unknown>>`
946:     select * from delegations where id = ${DELEGATION_ID} limit 1
947:   `;
948:   return rows.length ? mapDelegation(rows[0]) : null;
949: }
