963: async function readDelegationUsageTx(sql: Sql, delegationId: string): Promise<DelegationUsage> {
964:   const now = new Date();
965:   const day = now.toISOString().slice(0, 10);
966:   const month = now.toISOString().slice(0, 7);
967:   const rows = await sql<{ n: number; cents: number; month_n: number; month_cents: number }>`
968:     select
969:       count(*) filter (where usage_day = ${day})::int as n,
970:       coalesce(sum(amount_cents) filter (where usage_day = ${day}), 0)::int as cents,
971:       count(*) filter (where usage_month = ${month})::int as month_n,
972:       coalesce(sum(amount_cents) filter (where usage_month = ${month}), 0)::int as month_cents
973:     from delegation_usage
974:     where delegation_id = ${delegationId}
975:   `;
976:   const row = rows[0];
977:   return {
978:     usedToday: num(row?.n),
979:     spentTodayCents: num(row?.cents),
980:     usedThisMonth: num(row?.month_n),
981:     spentThisMonthCents: num(row?.month_cents),
982:   };
983: }
