985: /**
986:  * Save the delegation. This is the founder writing down, in advance, exactly
987:  * how far the office may go on its own. Every change is audited, so the
988:  * authority that allowed a given action can always be read back.
989:  */
990: export async function saveDelegation(input: {
991:   label: string;
992:   status?: "active" | "paused";
993:   maxAmountCents: number;
994:   maxActionsPerDay: number;
995:   maxActionsPerMonth: number;
996:   allowedActions: string[];
997:   allowedRateIds: string[];
998:   allowCustomerMail: boolean;
999:   allowAutoReconcile: boolean;
1000:   requireAcceptedQuote: boolean;
1001: }): Promise<{ ok: true; delegation: DelegationPolicy } | { ok: false; error: string }> {
1002:   const label = (input.label ?? "").replace(/\s+/g, " ").trim().slice(0, 120);
1003:   if (label.length < 3)
1004:     return { ok: false, error: "Give the delegation a name you will recognise." };
1005:   const actions = (input.allowedActions ?? []).filter((action): action is DelegationAction =>
1006:     (DELEGATABLE_ACTIONS as readonly string[]).includes(action),
1007:   );
1008:   if (actions.length !== (input.allowedActions ?? []).length) {
1009:     return { ok: false, error: "One of those actions cannot be delegated." };
1010:   }
1011:   const rates = (input.allowedRateIds ?? []).filter((id) => delegatableRateIds().includes(id));
1012:   const maxAmount = Math.max(0, Math.round(Number(input.maxAmountCents) || 0));
1013:   if (maxAmount <= 0) return { ok: false, error: "Set a limit for a single action." };
1014:   const perDay = Math.max(0, Math.round(Number(input.maxActionsPerDay) || 0));
1015:   const perMonth = Math.max(0, Math.round(Number(input.maxActionsPerMonth) || 0));
1016:   if (perDay <= 0 || perMonth <= 0) {
1017:     return { ok: false, error: "Set how many actions the delegation may take per day and month." };
1018:   }
1019:   if (perMonth < perDay) {
1020:     return { ok: false, error: "The monthly limit cannot be smaller than the daily limit." };
1021:   }
1022:   if (actions.includes("send_customer_mail") && !input.allowCustomerMail) {
1023:     return { ok: false, error: "Allow customer email, or remove it from the delegated actions." };
1024:   }
1025: 
1026:   const sql = await getSql();
1027:   const status = input.status === "paused" ? "paused" : "active";
1028:   await sql`
1029:     insert into delegations (
1030:       id, label, status, max_amount_cents, max_actions_per_day, max_actions_per_month,
1031:       allowed_actions_json, allowed_rate_ids_json, allow_customer_mail,
1032:       allow_auto_reconcile, require_accepted_quote, created_at, updated_at, revoked_at
1033:     ) values (
1034:       ${DELEGATION_ID}, ${label}, ${status}, ${maxAmount}, ${perDay}, ${perMonth},
1035:       ${JSON.stringify(actions)}, ${JSON.stringify(rates)}, ${input.allowCustomerMail === true},
1036:       ${input.allowAutoReconcile === true}, ${input.requireAcceptedQuote !== false},
1037:       now(), now(), null
1038:     )
1039:     on conflict (id) do update set
1040:       label = excluded.label,
1041:       status = excluded.status,
1042:       max_amount_cents = excluded.max_amount_cents,
1043:       max_actions_per_day = excluded.max_actions_per_day,
1044:       max_actions_per_month = excluded.max_actions_per_month,
1045:       allowed_actions_json = excluded.allowed_actions_json,
1046:       allowed_rate_ids_json = excluded.allowed_rate_ids_json,
1047:       allow_customer_mail = excluded.allow_customer_mail,
1048:       allow_auto_reconcile = excluded.allow_auto_reconcile,
1049:       require_accepted_quote = excluded.require_accepted_quote,
1050:       updated_at = now(),
1051:       revoked_at = null
1052:   `;
1053:   const delegation = await readDelegationTx(sql);
1054:   await appendAudit(
1055:     "delegation_saved",
1056:     `Delegation "${label}" ${status === "paused" ? "paused" : "active"}`,
1057:     `Actions: ${actions.length ? actions.join(", ") : "none"}. Limit R${(maxAmount / 100).toFixed(2)} per action, ${perDay} per day, ${perMonth} per month. Customer email ${input.allowCustomerMail ? "on" : "off"}. Automatic payment matching ${input.allowAutoReconcile ? "on" : "off"}.`,
1058:     "founder",
1059:   );
1060:   return { ok: true, delegation: delegation as DelegationPolicy };
1061: }
1062: 
1063: /**
1064:  * Revoke the delegation. It takes effect on the very next action the office
1065:  * would take; there is no grace period and no queue of work already approved.
1066:  */
1067: export async function revokeDelegation(
1068:   reason: string,
1069: ): Promise<{ ok: true } | { ok: false; error: string }> {
1070:   return withChain(async (tx) => {
1071:     const rows = await tx<{ id: string }>`select id from delegations where id = ${DELEGATION_ID}`;
1072:     if (!rows.length) return { ok: false, error: "There is no delegation to revoke." };
1073:     await tx`
1074:       update delegations
1075:       set status = 'revoked', revoked_at = now(), updated_at = now()
1076:       where id = ${DELEGATION_ID}
1077:     `;
1078:     await appendAuditTx(
1079:       tx,
1080:       "delegation_revoked",
1081:       "Delegation revoked",
1082:       `The founder revoked the standing delegation. ${reason.replace(/\s+/g, " ").trim().slice(0, 400)}`,
1083:       "founder",
1084:     );
1085:     return { ok: true };
1086:   });
1087: }
