1089: async function recordDecisionTx(
1090:   sql: Sql,
1091:   input: {
1092:     agentId: string;
1093:     action: ProposedAction;
1094:     status: DecisionRow["status"];
1095:     trace: ProvisionCheck[];
1096:     reversibility: DecisionRow["reversibility"];
1097:     observation: Record<string, Json>;
1098:     delegationId?: string | null;
1099:   },
1100: ): Promise<string> {
1101:   const previous = await readAuditHead(sql);
1102:   const id = randomUUID();
1103:   const evidenceHash = sha256Hex(stableStringify(input.action));
1104:   // The chain covers everything that defines the decision, including the
1105:   // observation, so a tampered row cannot be re-hashed into something valid.
1106:   const recordHash = chainHash(previous, {
1107:     id,
1108:     agentId: input.agentId,
1109:     action: input.action,
1110:     status: input.status,
1111:     trace: input.trace,
1112:     observation: input.observation,
1113:     evidenceHash,
1114:     delegationId: input.delegationId ?? null,
1115:   });
1116:   await sql`
1117:     insert into decisions (
1118:       id, agent_id, action_kind, title, rationale, status, confidence, reversibility,
1119:       amount_cents, constitutional_trace_json, observation_json, action_json,
1120:       evidence_hash, previous_hash, record_hash, delegation_id
1121:     ) values (
1122:       ${id}, ${input.agentId}, ${input.action.kind}, ${input.action.title},
1123:       ${input.action.rationale}, ${input.status}, ${input.action.confidence},
1124:       ${input.reversibility}, ${input.action.amountCents}, ${JSON.stringify(input.trace)},
1125:       ${JSON.stringify(input.observation)}, ${JSON.stringify(input.action)},
1126:       ${evidenceHash}, ${previous}, ${recordHash}, ${input.delegationId ?? null}
1127:     )
1128:   `;
1129:   await sql`
1130:     update company_state set last_audit_hash = ${recordHash}, updated_at = now()
1131:     where id = ${COMPANY.id}
1132:   `;
1133:   await sql`
1134:     update agents
1135:     set decisions_count = decisions_count + 1,
1136:         escalations_count = escalations_count + ${input.status === "escalated" ? 1 : 0},
1137:         last_heartbeat = now(),
1138:         current_task = ${input.action.title},
1139:         status = ${input.status === "blocked" ? "blocked" : "idle"}
1140:     where id = ${input.agentId}
1141:   `;
1142:   return id;
1143: }
