1145: /**
1146:  * Apply one action's side effects. Always called with the transaction/handle the
1147:  * caller wants the write to land in, so a ledger entry and its balance movement
1148:  * can never be observed apart.
1149:  */
1150: async function executeAuthorized(
1151:   sql: Sql,
1152:   agentId: string,
1153:   action: ProposedAction,
1154:   approvalId?: string,
1155: ): Promise<{ documentId?: string }> {
1156:   const companyName = (action.companyName || String(action.payload.companyName ?? "")).trim();
1157:   const amount = Math.max(0, Math.round(action.amountCents || 0));
1158: 
1159:   switch (action.kind) {
1160:     case "route_inbound": {
1161:       if (action.relatedId) {
1162:         await sql`
1163:           update inbound_items
1164:           set status = 'routed', routed_to = ${String(action.payload.routedTo ?? agentId)}
1165:           where id = ${action.relatedId}
1166:         `;
1167:       }
1168:       break;
1169:     }
1170:     case "draft_reply": {
1171:       const id = randomUUID();
1172:       const body = typeof action.payload.body === "string" ? action.payload.body : action.rationale;
1173:       await sql`
1174:         insert into documents (id, title, kind, status, summary, related_id)
1175:         values (${id}, ${action.title}, 'correspondence', 'draft', ${body}, ${action.relatedId ?? null})
1176:       `;
1177:       break;
1178:     }
1179:     case "create_lead": {
1180:       const id = randomUUID();
1181:       // The lead must carry the customer's OWN words, not the agent's summary of
1182:       // them. Downstream duties (qualifying, scoring, the sales handoff) decide
1183:       // on this text, and an agent-authored paraphrase would make them score an
1184:       // agent's optimism rather than what the buyer actually wrote.
1185:       const evidence =
1186:         typeof action.payload.evidence === "string" && action.payload.evidence.trim()
1187:           ? action.payload.evidence.trim().slice(0, 4000)
1188:           : action.rationale;
1189:       await sql`
1190:         insert into leads (id, company_name, source, stage, score, summary, inbound_id)
1191:         values (
1192:           ${id},
1193:           ${companyName || "Unnamed company"},
1194:           ${String(action.payload.source ?? "inbound")},
1195:           ${String(action.payload.stage ?? "engaged")},
1196:           ${num(action.payload.score, 40)},
1197:           ${evidence},
1198:           ${action.relatedId ?? null}
1199:         )
1200:       `;
1201:       await sql`
1202:         update inbound_items
1203:         set status = 'routed', routed_to = ${agentId}
1204:         where id = ${action.relatedId ?? ""}
1205:       `;
1206:       break;
1207:     }
1208:     case "update_lead": {
1209:       if (action.relatedId) {
1210:         // Callers that only moved the stage (`keepSummary`) must not overwrite
1211:         // the lead's own words: the summary is the buyer's text, and downstream
1212:         // duties score what the buyer actually wrote, not the agent's note.
1213:         if (action.payload.keepSummary === true) {
1214:           await sql`
1215:             update leads
1216:             set stage = ${String(action.payload.stage ?? "engaged")},
1217:                 score = ${num(action.payload.score, 50)},
1218:                 updated_at = now()
1219:             where id = ${action.relatedId}
1220:           `;
1221:         } else {
1222:           await sql`
1223:             update leads
1224:             set stage = ${String(action.payload.stage ?? "engaged")},
1225:                 score = ${num(action.payload.score, 50)},
1226:                 summary = ${action.rationale},
1227:                 updated_at = now()
1228:             where id = ${action.relatedId}
1229:           `;
1230:         }
1231:       }
1232:       break;
1233:     }
1234:     case "draft_campaign":
1235:     case "activate_campaign": {
1236:       const budget = amount;
1237:       const campaignId = action.relatedId ?? randomUUID();
1238:       if (action.relatedId) {
1239:         const campaign = await sql<{ id: string }>`
1240:           select id from campaigns where id = ${action.relatedId} limit 1
1241:         `;
1242:         if (!campaign.length) throw new Error("The campaign to update is no longer on file.");
1243:       }
1244:       const books = await loadCompanyTx(sql);
1245:       const canPay =
1246:         action.kind === "activate_campaign" && budget > 0 && books.treasuryCents >= budget;
1247:       const status =
1248:         action.kind === "activate_campaign"
1249:           ? budget === 0
1250:             ? "active"
1251:             : canPay
1252:               ? "active"
1253:               : "awaiting_budget"
1254:           : budget > 0
1255:             ? "awaiting_budget"
1256:             : "draft";
1257:       const spend = canPay ? budget : 0;
1258:       if (action.relatedId) {
1259:         await sql`
1260:           update campaigns
1261:           set name = ${action.title},
1262:               channel = ${String(action.payload.channel ?? "owned")},
1263:               status = ${status},
1264:               budget_cents = ${budget},
1265:               spend_cents = ${spend},
1266:               summary = ${action.rationale}
1267:           where id = ${action.relatedId}
1268:         `;
1269:       } else {
1270:         await sql`
1271:           insert into campaigns (id, name, channel, status, budget_cents, spend_cents, summary)
1272:           values (
1273:             ${campaignId}, ${action.title}, ${String(action.payload.channel ?? "owned")},
1274:             ${status}, ${budget}, ${spend}, ${action.rationale}
1275:           )
1276:         `;
1277:       }
1278:       if (canPay) {
1279:         const vat = expenseVat(action.payload.vatTreatment, budget);
1280:         const entryId = randomUUID();
1281:         await sql`
1282:           insert into ledger_entries (id, kind, counterparty, amount_cents, vat_cents, status, memo, related_id)
1283:           values (
1284:             ${entryId}, 'expense', ${String(action.payload.vendor ?? "Media")}, ${budget}, ${vat},
1285:             'paid', ${action.rationale}, ${campaignId}
1286:           )
1287:         `;
1288:         await sql`
1289:           update company_state
1290:           set treasury_cents = treasury_cents - ${budget}, updated_at = now()
1291:           where id = ${COMPANY.id}
1292:         `;
1293:       }
