export type ModelTarget = {
  provider:
    | "workers-ai"
    | "xai"
    | "huggingface"
    | "opencode"
    | "opencode-zen"
    | "zen";
  url: string;
  key: string;
  model: string;
  headers?: Record<string, string>;
};

const OPENCODE_ZEN_URL = "https://opencode.ai/zen/v1/chat/completions";
const OPENCODE_ZEN_DEFAULT_MODEL = "mimo-v2.6-flash-free";
const OPENCODE_ZEN_HEADERS = {
  "User-Agent": "opencode/1.15.9 ai-sdk/provider-utils/4.0.23 runtime/bun/1.3.14",
  "X-Opencode-Client": "cli",
  "X-Opencode-Project": "global",
};

function opencodeModel(env: Record<string, string | undefined>): string {
  return (
    env.OPENCODE_ZEN_MODEL?.trim() ||
    env.OPENCODE_MODEL?.trim() ||
    env.ZEN_MODEL?.trim() ||
    OPENCODE_ZEN_DEFAULT_MODEL
  );
}

function opencodeKey(env: Record<string, string | undefined>): string {
  return (
    env.OPENCODE_ZEN_API_KEY?.trim() ||
    env.OPENCODE_API_KEY?.trim() ||
    env.ZEN_API_KEY?.trim() ||
    "public"
  );
}

/**
 * Chooses the reasoning model.
 *
 * The office prefers a configured provider in this order:
 * 1) Cloudflare Workers AI when both host credentials are present
 * 2) xAI when API key + model are configured
 * 3) Hugging Face free/public inference when the host selects it
 * 4) OpenCode Zen free models, which need no key and make the office able to
 *    reason unattended even on a bare host
 *
 * The founder controls the actual business actions; these choices only widen the
 * assistant's research and drafting capacity without allowing unattended sales.
 */
export function resolveModelTarget(env: Record<string, string | undefined>): ModelTarget | null {
  const account = env.CLOUDFLARE_ACCOUNT_ID?.trim();
  const token = env.CLOUDFLARE_API_TOKEN?.trim();
  const xai = env.XAI_API_KEY?.trim();
  const hfModel = env.HUGGINGFACE_MODEL?.trim();
  const hfToken = env.HUGGINGFACE_API_KEY?.trim() || env.HF_TOKEN?.trim();
  const wanted = env.AI_PROVIDER?.trim().toLowerCase();

  // OpenCode Zen / OpenCode free models. No key is required: the public endpoint
  // answers with `Authorization: Bearer public`.
  if (
    wanted === "opencode" ||
    wanted === "opencode-zen" ||
    wanted === "zen" ||
    wanted === "opencode-zen-completions"
  ) {
    return {
      provider: wanted === "opencode" ? "opencode" : wanted === "zen" ? "zen" : "opencode-zen",
      url: OPENCODE_ZEN_URL,
      key: opencodeKey(env),
      model: opencodeModel(env),
      headers: OPENCODE_ZEN_HEADERS,
    };
  }

  if (wanted === "xai" && xai) {
    return {
      provider: "xai",
      url: "https://api.x.ai/v1/chat/completions",
      key: xai,
      model: env.XAI_MODEL?.trim() || "grok-4.5",
    };
  }

  if (wanted === "huggingface") {
    const model = hfModel || "google/gemma-2-2b-it";
    return {
      provider: "huggingface",
      url: `https://api-inference.huggingface.co/models/${model}`,
      key: hfToken || "",
      model,
    };
  }

  if (wanted !== "xai" && account && token && /^[a-f0-9]{32}$/i.test(account)) {
    return {
      provider: "workers-ai",
      url: `https://api.cloudflare.com/client/v4/accounts/${account}/ai/v1/chat/completions`,
      key: token,
      model: env.WORKERS_AI_MODEL?.trim() || "@cf/meta/llama-3.3-70b-instruct-fp8-fast",
    };
  }

  if (xai) {
    return {
      provider: "xai",
      url: "https://api.x.ai/v1/chat/completions",
      key: xai,
      model: env.XAI_MODEL?.trim() || "grok-4.5",
    };
  }

  if (hfModel || hfToken) {
    const model = hfModel || "google/gemma-2-2b-it";
    return {
      provider: "huggingface",
      url: `https://api-inference.huggingface.co/models/${model}`,
      key: hfToken || "",
      model,
    };
  }

  // Free, no-key fallback so the office can reason on its own even when no
  // provider has been configured. This is what makes the business fully
  // autonomous out of the box.
  return {
    provider: "opencode-zen",
    url: OPENCODE_ZEN_URL,
    key: opencodeKey(env),
    model: opencodeModel(env),
    headers: OPENCODE_ZEN_HEADERS,
  };
}

